def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'

    me = [h[0] for h in history]
    opp = [h[1] for h in history]

    opp_defects = 0
    my_defects = 0
    for a in opp:
        if a == 'D':
            opp_defects += 1
    for a in me:
        if a == 'D':
            my_defects += 1

    last_my = me[-1]
    last_opp = opp[-1]
    remaining = 100 - n

    # --- Early cooperation building ---
    if n < 4:
        return 'C'

    # --- Hard punishment of frequent defectors ---
    if opp_defects >= max(3, n * 3 // 5):
        # Probe rarely to see if they return to cooperation
        if n % 13 == 0:
            return 'C'
        return 'D'

    # --- All-defect opponent ---
    if opp_defects == n and n >= 3:
        if n % 19 == 0:
            return 'C'
        return 'D'

    # --- Endgame: exploit unconditionally cooperative opponents ---
    if remaining <= 2:
        if opp_defects == 0:
            return 'D'
        if last_opp == 'D':
            return 'D'
        if remaining == 1:
            return 'D'
        return 'C'

    # --- Near-endgame aggression ---
    if remaining <= 6:
        # If opponent is fairly cooperative, start pulling D
        if opp_defects * 3 <= n:
            return 'D'
        if last_opp == 'C' and opp_defects * 2 <= n:
            return 'D'
        if last_opp == 'D':
            return 'D'
        return 'C'

    # --- Forgiveness: break mutual-defect spirals ---
    # Count trailing defections of both
    opp_consec_d = 0
    for a in reversed(opp):
        if a == 'D':
            opp_consec_d += 1
        else:
            break
    my_consec_d = 0
    for a in reversed(me):
        if a == 'D':
            my_consec_d += 1
        else:
            break

    # If both stuck defecting, try to restart cooperation
    if opp_consec_d >= 2 and my_consec_d >= 2:
        # Reasonably often attempt to break the loop
        if rng.random() < 0.5:
            return 'C'
        return 'D'

    # --- Opponent cooperated last ---
    if last_opp == 'C':
        # If we defected last and they still cooperated, occasionally keep
        # exploiting a very forgiving opponent, but not too greedily
        if last_my == 'D':
            if opp_defects <= 1 and remaining > 20:
                # They almost never retaliate - exploit a bit more
                if rng.random() < 0.5:
                    return 'D'
            return 'C'
        # If opponent has been very clean, occasionally probe with D early
        if opp_defects == 0:
            if n >= 6 and n <= 30 and n % 7 == 0:
                if rng.random() < 0.4:
                    return 'D'
        return 'C'

    # --- Opponent defected last ---
    # Retaliate, with forgiveness if opponent is generally cooperative
    if opp_defects * 2 <= n and rng.random() < 0.4:
        # Mostly cooperative opponent had a slip - forgive
        return 'C'
    # If opponent defected only occasionally recently, forgive sometimes
    if n >= 6:
        recent = opp[-6:]
        rd = 0
        for a in recent:
            if a == 'D':
                rd += 1
        if rd <= 2 and rng.random() < 0.3:
            return 'C'
    return 'D'
